$ErrorActionPreference='Stop'
$root='F:\JericoEngine\JericoEngine';$base=Join-Path $root 'build\n0-validation\local-packages';$build=Join-Path $base 'python-v143-rev2\consumer-retry';$package=Join-Path $base 'python-v143-rev2\extracted\python-3.10.13-je-rev1-windows';$freeze=Join-Path $base 'source-freeze-python-parent-rev2.json';$ctest='C:\Program Files\CMake\bin\ctest.exe';$cmake='C:\Program Files\CMake\bin\cmake.exe';$prefix=Join-Path $base 'python-consumer-retry-ctest-release'
function Snapshot-Inputs([string]$label){$mf=Get-Content -LiteralPath $freeze -Raw|ConvertFrom-Json;$ss=@($mf|ForEach-Object{$p=Join-Path $root $_.path;[pscustomobject]@{path=$_.path;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash}});$ps=@(Get-ChildItem -LiteralPath $package -File -Recurse|ForEach-Object{$h=Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256;[pscustomobject]@{path=$_.FullName.Substring($package.Length).TrimStart('\');bytes=$_.Length;sha256=$h.Hash}}|Sort-Object path);$dest="$prefix-package-$label.json";$ps|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $dest -Encoding UTF8;[pscustomobject]@{freeze_sha256=(Get-FileHash -LiteralPath $freeze -Algorithm SHA256).Hash;source=$ss;package_files=$ps.Count;package_bytes=($ps|Measure-Object bytes -Sum).Sum;package_snapshot=$dest;archive_sha256=(Get-FileHash -LiteralPath (Join-Path (Split-Path $package -Parent|Split-Path -Parent) 'package-retry\python-3.10.13-je-rev1-windows.tar.xz') -Algorithm SHA256).Hash;ctest_sha256=(Get-FileHash -LiteralPath $ctest -Algorithm SHA256).Hash;cmake_sha256=(Get-FileHash -LiteralPath $cmake -Algorithm SHA256).Hash}}
$a1='--test-dir';$a2=$build;$a3='-C';$a4='Release';$a5='--output-on-failure';[string[]]$argv=@($a1,$a2,$a3,$a4,$a5);if($argv.Count -ne 5 -or $argv[0] -ne '--test-dir' -or $argv[2] -ne '-C' -or $argv[3] -ne 'Release'){throw 'ctest argv invalid'}
$venvDebug=Join-Path $build 'venv-Debug';$venvRelease=Join-Path $build 'venv-Release';if((Test-Path $venvDebug) -or (Test-Path $venvRelease)){throw 'runtime venv path preexists'}
$env:PIP_NO_INDEX='1';$env:PIP_CONFIG_FILE='NUL';$env:PIP_DISABLE_PIP_VERSION_CHECK='1';$env:PYTHONNOUSERSITE='1';$env:PYTHONPATH='';$env:PYTHONHOME='';$meta=[pscustomobject]@{cwd=(Get-Location).Path;executable=$ctest;argv=@($argv);argv_count=$argv.Count;mode='CTest Release all';started=(Get-Date).ToString('o');inputs_before=(Snapshot-Inputs 'before');venv_paths=@($venvDebug,$venvRelease)};$meta|ConvertTo-Json -Depth 8|Set-Content -LiteralPath "$prefix-argv-before.json" -Encoding UTF8
$sw=[Diagnostics.Stopwatch]::StartNew();$output=& $ctest @argv 2>&1;$exit=$LASTEXITCODE;$sw.Stop();$output|Out-String|Set-Content -LiteralPath "$prefix.log" -Encoding UTF8;$exit|Set-Content -LiteralPath "$prefix.exitcode" -Encoding ASCII;('{0:N3}s' -f $sw.Elapsed.TotalSeconds)|Set-Content -LiteralPath "$prefix.elapsed.txt" -Encoding ASCII;$after=Snapshot-Inputs 'after';[pscustomobject]@{started=$meta.started;finished=(Get-Date).ToString('o');exitcode=$exit;elapsed_seconds=$sw.Elapsed.TotalSeconds;before=$meta.inputs_before;after=$after;venv_debug_exists=(Test-Path $venvDebug);venv_release_exists=(Test-Path $venvRelease)}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath "$prefix-inputs-after.json" -Encoding UTF8;Write-Output ("exit=$exit elapsed={0:N3}s" -f $sw.Elapsed.TotalSeconds)
